const { execFileSync } = await import('node:child_process');
const mod = await import('file://' + $root + '/packages/utils/dist/handlers/tool-status.js');
execFileSync('node', ['bin/koala-codex.js', 'session_brief'], {
  cwd: $root,
  encoding: 'utf8',
  env: { ...process.env, LATTICE_ACTIVITY_ROLE: 'reviewer' }
});
const brief = execFileSync('node', ['bin/koala-codex.js', 'session_brief'], { cwd: $root, encoding: 'utf8' });
const res = mod.createToolStatusHandlers({ root: $root }).tool_status({ source: 'codex', role: 'reviewer', days: 1, format: 'json' });
return {
  role: res.summary.role,
  reviewerCount: (res.summary.byRole?.reviewer || 0) >= 1,
  hasRows: (res.top || []).length >= 1,
  briefShowsReviewer: brief.includes('[codex/reviewer/ok]')
};

const { mkdirSync, writeFileSync, mkdtempSync, rmSync } = await import('node:fs');
const { tmpdir } = await import('node:os');
const { join } = await import('node:path');
const tempRoot = mkdtempSync(join(tmpdir(), 'koala-role-mixed-'));
const NL = String.fromCharCode(10);
try {
  mkdirSync(join(tempRoot, 'docs', 'story'), { recursive: true });
  writeFileSync(join(tempRoot, 'docs', 'story', 'activity.jsonl'), [
    JSON.stringify({ source: 'codex', tool: 'session_brief', status: 'ok', endTime: new Date().toISOString() }),
    JSON.stringify({ source: 'codex', role: 'reviewer', tool: 'session_brief', status: 'ok', endTime: new Date().toISOString() })
  ].join(NL) + NL);
  const mod = await import('file://' + $root + '/packages/utils/dist/handlers/tool-status.js');
  const res = mod.createToolStatusHandlers({ root: tempRoot }).tool_status({ source: 'codex', days: 1, format: 'json' });
  return {
    unknownSeen: (res.summary.byRole?.unknown || 0) === 1,
    reviewerSeen: (res.summary.byRole?.reviewer || 0) === 1
  };
} finally { rmSync(tempRoot, { recursive: true, force: true }); }

