const { appendFileSync, readFileSync, writeFileSync } = await import('node:fs');
const { join } = await import('node:path');
const toolStatusMod = await import('file://' + $root + '/packages/utils/dist/handlers/tool-status.js');
const logPath = join($root, 'docs', 'story', 'activity.jsonl');
const original = readFileSync(logPath, 'utf8');
const NL = String.fromCharCode(10);
appendFileSync(logPath, JSON.stringify({ source: 'codex', tool: 'session_brief', status: 'ok', endTime: new Date().toISOString() }) + NL);
try {
  const brief = (await import('node:child_process')).execFileSync('node', ['bin/koala-codex.js', 'session_brief'], { cwd: $root, encoding: 'utf8' });
  const res = toolStatusMod.createToolStatusHandlers({ root: $root }).tool_status({ source: 'codex', days: 1, format: 'json' });
  return {
    briefShowsUnknown: brief.includes('/unknown/ok]'),
    statsExposeUnknown: (res.summary.byRole?.unknown || 0) >= 1
  };
} finally { writeFileSync(logPath, original); }
